css_snippet:
p {
  hyphens: auto;
  text-align: justify;
  -webkit-hyphens: auto; /* For Safari */
  -ms-hyphens: auto;     /* For IE/Edge */
  overflow-wrap: break-word; /* Ensures long words break if hyphens aren't enough */
}

/* Ensure language is declared for optimal hyphenation accuracy */
html {
  lang: "en"; /* Adjust to your content's language */
}
